<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { APIError, post, request } from '../api/client'
import { memberLogin, type MediaUser, type MediaLibrary, type MediaItem } from '../api/mediaServer'
const user=ref<MediaUser>(), libraries=ref<MediaLibrary[]>([]), items=ref<MediaItem[]>([]), selected=ref(''), total=ref(0), page=ref(1), query=ref('')
const username=ref(''), password=ref(''), current=ref(''), next=ref(''), confirm=ref(''), changing=ref(false), busy=ref(true), error=ref(''), notice=ref(''), broken=ref(new Set<string>())
const passwordPage=computed(()=>user.value?.mustChangePassword||changing.value)
function expire(e:unknown){if(e instanceof APIError&&e.status===401){user.value=undefined;items.value=[];libraries.value=[]}error.value=e instanceof Error?e.message:'请求失败'}
async function loadItems(){if(!selected.value){items.value=[];total.value=0;return}busy.value=true;error.value='';try{const p=await request<{items:MediaItem[];total:number}>(`/member/libraries/${selected.value}/items?${new URLSearchParams({page:String(page.value),pageSize:'24',q:query.value})}`);items.value=p.items;total.value=p.total}catch(e){items.value=[];expire(e)}finally{busy.value=false}}
async function loadLibraries(){libraries.value=await request('/member/libraries');selected.value=libraries.value.find(l=>l.id===selected.value)?.id||libraries.value[0]?.id||'';await loadItems()}
async function initialize(){try{user.value=(await request<{user:MediaUser}>('/member/auth/session')).user;if(!user.value.mustChangePassword)await loadLibraries()}catch(e){if(!(e instanceof APIError&&e.status===401))expire(e)}finally{busy.value=false}}
async function login(){busy.value=true;error.value='';notice.value='';try{user.value=(await memberLogin(username.value,password.value)).user;password.value='';if(!user.value.mustChangePassword)await loadLibraries()}catch(e){expire(e)}finally{busy.value=false}}
async function logout(){busy.value=true;error.value='';try{await post('/member/auth/logout',{});user.value=undefined;items.value=[];libraries.value=[];changing.value=false;current.value='';next.value='';confirm.value=''}catch(e){expire(e)}finally{busy.value=false}}
async function change(){busy.value=true;error.value='';try{await post('/member/auth/password',{currentPassword:current.value,newPassword:next.value,confirmPassword:confirm.value});user.value=undefined;items.value=[];libraries.value=[];current.value='';next.value='';confirm.value='';changing.value=false;notice.value='密码已更新，请使用新密码重新登录'}catch(e){expire(e)}finally{busy.value=false}}
function search(){page.value=1;void loadItems()}
onMounted(initialize)
</script>
<template>
 <main class="member-shell"><header class="member-header"><div><span class="page-kicker">MEDIA TOOL / 内置媒体库</span><h1>{{!user?'媒体用户登录':passwordPage?'修改媒体密码':'我的媒体库'}}</h1></div><div v-if="user" class="member-actions"><span>{{user.displayName}}</span><el-button v-if="!passwordPage" @click="changing=true;error=''">修改密码</el-button><el-button :loading="busy" @click="logout">退出</el-button></div></header>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/>
 <section v-if="!user" class="panel member-login" v-loading="busy"><p>使用管理员为你创建的媒体账号。此入口不接受管理员账号或 Emby 账号。</p><el-form label-position="top" @submit.prevent="login"><el-form-item label="媒体账号" for="member-username"><el-input id="member-username" v-model="username" autocomplete="username" maxlength="32"/></el-form-item><el-form-item label="媒体密码" for="member-password"><el-input id="member-password" v-model="password" type="password" show-password autocomplete="current-password"/></el-form-item><el-button native-type="submit" type="primary" :loading="busy">进入媒体库</el-button></el-form><p class="field-hint">未开放公开注册；忘记密码请联系管理员重置。</p></section>
 <section v-else-if="passwordPage" class="panel member-login"><p>{{user.mustChangePassword?'初始密码或重置密码不能用于浏览媒体，请先修改。':'修改密码后所有媒体会话都会失效。'}}</p><el-form label-position="top" @submit.prevent="change"><el-form-item label="当前媒体密码" for="member-current"><el-input id="member-current" v-model="current" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新媒体密码" for="member-next"><el-input id="member-next" v-model="next" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新媒体密码" for="member-confirm"><el-input id="member-confirm" v-model="confirm" type="password" show-password autocomplete="new-password"/></el-form-item><p class="field-hint">6–20个字符，新密码不能与当前密码相同。</p><el-button v-if="!user.mustChangePassword" @click="changing=false">取消</el-button><el-button native-type="submit" type="primary" :loading="busy">更新密码并重新登录</el-button></el-form></section>
 <template v-else><p class="member-note">目录预览 · 播放功能尚未开放，仅展示授权范围内已确认且文件在库的媒体。</p><section class="panel member-toolbar"><el-select v-model="selected" aria-label="我的媒体库" placeholder="尚无媒体库权限" @change="search"><el-option v-for="library in libraries" :key="library.id" :label="library.name" :value="library.id"/></el-select><el-input v-model="query" aria-label="搜索我的媒体" placeholder="搜索标题" clearable @keyup.enter="search"/><el-button :loading="busy" @click="search">搜索</el-button></section>
 <section class="member-grid" v-loading="busy" aria-label="授权媒体目录"><article v-for="item in items" :key="item.id" class="panel member-card"><img v-if="item.poster&&!broken.has(item.id)" :src="item.poster" :alt="`${item.title}海报`" loading="lazy" @error="broken.add(item.id)"/><div v-else class="member-placeholder">暂无海报</div><div><h2>{{item.title}}</h2><p>{{item.year||'年份未知'}} · {{item.mediaType==='movie'?'电影':'剧集'}}<span v-if="item.season!==undefined"> · S{{String(item.season).padStart(2,'0')}}</span><span v-if="item.episode!==undefined">E{{String(item.episode).padStart(2,'0')}}</span></p><p class="member-overview">{{item.overview||'暂无简介'}}</p></div></article></section><el-empty v-if="!busy&&!error&&!items.length" :description="libraries.length?'暂无已确认且在库的媒体':'尚无媒体库权限，请联系管理员'"/><el-pagination v-if="total>24" v-model:current-page="page" :total="total" :page-size="24" layout="prev,pager,next" @current-change="loadItems"/></template>
 </main>
</template>
<style scoped>
.member-shell{max-width:1200px;margin:0 auto;padding:32px 24px;min-height:100vh}.member-header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.member-header h1{font-size:28px;margin:8px 0}.member-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.member-actions .el-button{margin:0}.member-login{max-width:480px;margin:48px auto}.member-login p{line-height:1.8;color:var(--muted)}.member-login .el-button{min-height:44px}.member-note{color:var(--muted);line-height:1.8}.member-toolbar{display:flex;gap:12px;margin-bottom:24px}.member-toolbar .el-select{width:160px;flex-shrink:0}.member-toolbar .el-input{flex:1}.member-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;min-height:120px}.member-card{display:flex;align-items:flex-start;gap:16px;margin:0}.member-card img,.member-placeholder{width:90px;aspect-ratio:2/3;object-fit:cover;border-radius:6px;flex-shrink:0}.member-placeholder{display:grid;place-items:center;background:var(--canvas);color:var(--muted);font-size:12px}.member-card h2{font-size:17px;line-height:1.5;margin:0 0 8px;overflow-wrap:anywhere}.member-card p{color:var(--muted);line-height:1.6;font-size:13px}.member-overview{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.member-shell :deep(.el-alert){margin-bottom:16px}@media(max-width:700px){.member-shell{padding:20px 16px}.member-header{align-items:flex-start;flex-direction:column}.member-login{margin:24px auto}.member-grid{grid-template-columns:1fr}.member-toolbar{flex-wrap:wrap}.member-toolbar .el-select{width:100%}.member-toolbar .el-input{min-width:0}.member-toolbar .el-button{min-height:44px}.member-actions .el-button{min-height:44px}}
</style>
